const $=s=>document.querySelector(s),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let index=Math.max(0,Math.min(DECK.slides.length-1,(parseInt(location.hash.slice(1))||1)-1)),running=false,elapsed=0,last=0;
function paint(fill){let m=String(fill).match(/^(#[0-9a-f]{6})\/(\d+)$/i);return m?'fill="'+m[1]+'" fill-opacity="'+(+m[2]/100)+'"':'fill="'+fill+'"'}
function opSvg(o){if(o.kind==='rect')return `<rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" rx="${o.r||0}" ${paint(o.fill)} stroke="${o.stroke||'none'}"/>`;if(o.kind==='circle')return `<circle cx="${o.x}" cy="${o.y}" r="${o.r}" ${paint(o.fill)} stroke="${o.stroke||'none'}"/>`;if(o.kind==='line')return `<line x1="${o.x1}" y1="${o.y1}" x2="${o.x2}" y2="${o.y2}" stroke="${o.color}" stroke-width="${o.width}"/>`;if(o.kind==='text')return `<text x="${o.x}" y="${o.y+o.size*.94}" fill="${o.color}" font-family="Arial, sans-serif" font-size="${o.size}" font-weight="${o.bold?700:400}" aria-label="${esc(o.text)}">${o.lines.map((l,i)=>`<tspan x="${o.x}" dy="${i?o.size*1.24:0}">${esc(l)}</tspan>`).join('')}</text>`;if(o.kind==='image')return `<image href="../${o.file}" x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" preserveAspectRatio="${o.fit==='contain'?'xMidYMid meet':'xMidYMid slice'}"/>`;if(o.kind==='chart'){let bottom=o.y+o.h-35,barw=110,gap=100,max=2.1;return o.values.map((v,i)=>{let x=o.x+45+i*(barw+gap),h=v/max*(o.h-90);return `<rect x="${x}" y="${bottom-h}" width="${barw}" height="${h}" fill="#A33B32"/><text x="${x+barw/2}" y="${bottom-h-15}" text-anchor="middle" font-family="Arial" font-size="24" fill="#272726">${v.toLocaleString('pt-BR',{minimumFractionDigits:3,maximumFractionDigits:3})}</text><text x="${x+barw/2}" y="${bottom+29}" text-anchor="middle" font-family="Arial" font-size="20" fill="#72695F">${esc(o.categories[i])}</text>`}).join('')}if(o.kind==='table'){let widths=o.widths.map(v=>v/o.widths.reduce((a,b)=>a+b,0)*o.w),rh=o.h/o.rows.length;return o.rows.map((r,i)=>r.map((v,j)=>{let x=o.x+widths.slice(0,j).reduce((a,b)=>a+b,0),y=o.y+i*rh,active=i>0&&j>0&&v;return `<rect x="${x}" y="${y}" width="${widths[j]}" height="${rh}" fill="${active?'#A33B32':'#F6F2EC'}" stroke="#D9CFC2"/><text x="${x+7}" y="${y+rh*.65}" font-family="Arial" font-size="${j===0?14:15}" fill="${active?'white':'#272726'}">${esc(v)}</text>`}).join('')).join('')}return ''}
const nodes=DECK.slides.map((s,i)=>{let e=document.createElement('section');e.className='slide scene';e.hidden=true;e.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720" viewBox="0 0 1280 720" role="img" aria-label="${esc(s.title)}"><title>${esc(s.title)}</title><rect width="1280" height="720" fill="${s.background}"/>${s.ops.map(opSvg).join('')}</svg>`;$('#canvas').append(e);$('#jump').add(new Option((i+1)+'. '+s.title+(s.appendix?' · apêndice':''),i));return e});
function fit(){let r=$('#stage').getBoundingClientRect();$('#canvas').style.transform='scale('+Math.min(r.width/1280,r.height/720)+')'}
function show(i){index=Math.max(0,Math.min(nodes.length-1,i));nodes.forEach((n,j)=>n.hidden=j!==index);$('#position').textContent=(index+1)+' / '+nodes.length;$('#jump').value=index;$('#notes-text').textContent=DECK.slides[index].notes;let secs=DECK.slides[index].seconds,start=DECK.slides.slice(0,index).reduce((a,s)=>a+s.seconds,0);$('#pace').textContent=(DECK.slides[index].appendix?'Apêndice opcional · fora do roteiro de 20 minutos':'Fala sugerida: '+secs+' s · início em '+Math.floor(start/60)+':'+String(start%60).padStart(2,'0'))+' · ← → avançar · F tela cheia · N notas';$('#progress').style.width=(index+1)/nodes.length*100+'%';$('#prev').disabled=index===0;$('#next').disabled=index===nodes.length-1;history.replaceState(null,'','#'+(index+1));$('#announcement').textContent='Slide '+(index+1)+': '+DECK.slides[index].title;fit()}
async function full(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){$('#announcement').textContent='Use o modo de tela cheia do navegador, F11.'}}
$('#next').onclick=()=>show(index+1);$('#prev').onclick=()=>show(index-1);$('#jump').onchange=e=>show(+e.target.value);$('#fullscreen').onclick=full;$('#notes-toggle').onclick=()=>$('#notes').hidden=!$('#notes').hidden;$('#timer').onclick=()=>{running=!running;last=Date.now();$('#timer').textContent=running?'Ⅱ Pausar tempo':'▶ Retomar tempo'};setInterval(()=>{if(running){elapsed+=(Date.now()-last)/1000;last=Date.now()}$('#clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0')+' / 20:00'},500);window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',fit);window.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key==='Home')show(0);if(e.key==='End')show(nodes.length-1);if(e.key.toLowerCase()==='f')full();if(e.key.toLowerCase()==='n')$('#notes-toggle').click()});show(index);window.DECK_READY=true;
